<?php $title='Workout complete';$workoutMode=true;$totalSets=array_sum(array_map(fn($row)=>(int)$row['working_sets'],$state['summary'])); ?>
<div class="mx-auto max-w-2xl"><div class="mb-6 text-center"><p class="text-6xl">✅</p><h1 class="mt-3 text-3xl font-black">Workout complete</h1><p class="mt-1 text-zinc-400"><?= e($state['session']['session_type']) ?> · <?= $totalSets ?> working sets</p></div><div class="grid gap-3 sm:grid-cols-2"><?php foreach($state['summary'] as $row): ?><div class="card"><div class="flex justify-between gap-2"><strong><?= e($row['name']) ?></strong><?php if($row['personal_record']): ?><span class="text-sm text-emerald-400">🏆 PR</span><?php endif; ?></div><p class="mt-2 text-xl font-black"><?= e($row['best_weight']??'—') ?> kg × <?= (int)$row['best_reps'] ?></p></div><?php endforeach; ?></div><form method="post" action="<?= e(route('workouts.active.finish')) ?>" class="card mt-5"><?= csrf_field() ?><label for="workout-note">Optional workout note</label><textarea id="workout-note" name="notes" rows="2" placeholder="How did it feel?"></textarea><button class="btn-primary mt-4 w-full">Finish workout</button></form></div>
